import { forwardRef, useRef, useEffect, type InputHTMLAttributes } from 'react';

export type CheckboxProps = {
  checked?: boolean | 'indeterminate';
  disabled?: boolean;
  error?: boolean;
  label?: string;
  className?: string;
  onChange?: (checked: boolean) => void;
} & Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'checked' | 'onChange'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

const CheckIcon = () => (
  <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
    <path d="M2.5 6L5 8.5L9.5 3.5" />
  </svg>
);

const MinusIcon = () => (
  <svg viewBox="0 0 12 12" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
    <path d="M2.5 6H9.5" />
  </svg>
);

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(
  (
    {
      checked = false,
      disabled = false,
      error = false,
      label,
      className,
      onChange,
      ...props
    },
    forwardedRef,
  ) => {
    const innerRef = useRef<HTMLInputElement>(null);
    const ref = (forwardedRef as React.RefObject<HTMLInputElement>) || innerRef;
    const isIndeterminate = checked === 'indeterminate';
    const isChecked = checked === true;

    useEffect(() => {
      if (ref && 'current' in ref && ref.current) {
        ref.current.indeterminate = isIndeterminate;
      }
    }, [isIndeterminate, ref]);

    const classes = cn(
      'checkbox',
      disabled && 'checkbox--disabled',
      error && 'checkbox--error',
      className,
    );

    return (
      <label className={classes}>
        <input
          ref={ref}
          type="checkbox"
          className="checkbox__input"
          checked={isChecked || isIndeterminate}
          disabled={disabled}
          onChange={(e) => onChange?.(e.target.checked)}
          {...(isIndeterminate ? { 'data-indeterminate': '' } : {})}
          {...props}
        />
        <span className="checkbox__box">
          {isChecked && (
            <span className="checkbox__icon">
              <CheckIcon />
            </span>
          )}
          {isIndeterminate && (
            <span className="checkbox__icon">
              <MinusIcon />
            </span>
          )}
        </span>
        {label && <span className="checkbox__label">{label}</span>}
      </label>
    );
  },
);

Checkbox.displayName = 'Checkbox';

/* -------------------------------------------------------------------------
   Checkbox

   Single size (16px box, 40px touch target).
   Native <input type="checkbox"> hidden, visual replacement via label.

   States:  unchecked, checked, indeterminate, disabled, error
   ------------------------------------------------------------------------- */

.checkbox {
  display: inline-flex;
  align-items: center;
  gap: 0.5em;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  position: relative;
}

.checkbox--disabled {
  cursor: not-allowed;
  pointer-events: none;
}

/* Hidden native input with touch target */
.checkbox__input {
  position: absolute;
  width: 2.5rem;
  height: 2.5rem;
  margin: 0;
  padding: 0;
  opacity: 0;
  cursor: inherit;
  left: -0.75rem;
  top: 50%;
  transform: translateY(-50%);
}

/* Visual box */
.checkbox__box {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
  border-radius: var(--radius-sm);
  border: var(--stroke-thin) solid var(--checkbox-border-default);
  background-color: var(--checkbox-bg-unchecked);
  transition:
    background-color var(--duration-150) var(--easing-out),
    border-color var(--duration-150) var(--easing-out),
    box-shadow var(--duration-150) var(--easing-out);
}

/* Check / minus icon */
.checkbox__icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0.75rem;
  height: 0.75rem;
  color: var(--checkbox-fg-checked);
}

.checkbox__icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Hover ---- */

.checkbox__input:hover:not(:disabled) ~ .checkbox__box {
  background-color: var(--checkbox-bg-unchecked-hover);
}

.checkbox__input:checked:hover:not(:disabled) ~ .checkbox__box,
.checkbox__input[data-indeterminate]:hover:not(:disabled) ~ .checkbox__box {
  background-color: var(--checkbox-bg-checked-hover);
}

/* ---- Checked ---- */

.checkbox__input:checked ~ .checkbox__box,
.checkbox__input[data-indeterminate] ~ .checkbox__box {
  background-color: var(--checkbox-bg-checked);
  border-color: var(--checkbox-bg-checked);
}


/* ---- Focus ---- */

.checkbox__input:focus-visible ~ .checkbox__box {
  box-shadow: 0 0 0 var(--stroke-medium) var(--checkbox-focus-ring-default);
}

/* ---- Disabled ---- */

.checkbox__input:disabled ~ .checkbox__box {
  background-color: var(--checkbox-bg-disabled);
  border-color: var(--checkbox-bg-disabled);
}

.checkbox__input:disabled ~ .checkbox__box .checkbox__icon {
  color: var(--checkbox-fg-disabled);
}

/* ---- Error ---- */

.checkbox--error .checkbox__box {
  border-color: var(--checkbox-border-error);
}

/* ---- Label ---- */

.checkbox__label {
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  line-height: 1;
  color: var(--foreground);
}

.checkbox--disabled .checkbox__label {
  color: var(--muted-foreground);
}
